//! The error codes of SPEC section 2. Nothing else is ever sent to a client,
//! so the enum is closed and each variant maps to exactly one wire string.

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorCode {
    InvalidRequest,
    MissingParameter,
    InvalidParameterValue,
    QueueNameInvalid,
    QueueAlreadyExists,
    QueueDoesNotExist,
    ReceiptHandleInvalid,
    ReceiptHandleExpired,
    UnsupportedOperation,
    LimitExceeded,
}

impl ErrorCode {
    /// The exact string that appears in the `code` member of a failure response.
    pub fn as_str(self) -> &'static str {
        match self {
            ErrorCode::InvalidRequest => "InvalidRequest",
            ErrorCode::MissingParameter => "MissingParameter",
            ErrorCode::InvalidParameterValue => "InvalidParameterValue",
            ErrorCode::QueueNameInvalid => "QueueNameInvalid",
            ErrorCode::QueueAlreadyExists => "QueueAlreadyExists",
            ErrorCode::QueueDoesNotExist => "QueueDoesNotExist",
            ErrorCode::ReceiptHandleInvalid => "ReceiptHandleInvalid",
            ErrorCode::ReceiptHandleExpired => "ReceiptHandleExpired",
            ErrorCode::UnsupportedOperation => "UnsupportedOperation",
            ErrorCode::LimitExceeded => "LimitExceeded",
        }
    }
}

/// A command that failed. A failed command changes no state, so callers can
/// simply propagate this with `?` before mutating anything.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error {
    pub code: ErrorCode,
    pub message: String,
}

impl Error {
    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
        Error {
            code,
            message: message.into(),
        }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.code.as_str(), self.message)
    }
}

impl std::error::Error for Error {}

pub type Result<T> = std::result::Result<T, Error>;
EOF
cat > src/response.rs <<'EOF'
//! Builds the one-line JSON responses of SPEC section 1.

use serde_json::{Map, Value};

use crate::error::Error;

/// A success response: `{"ok": true}` plus the command's result members.
pub fn success(result: Map<String, Value>) -> Value {
    let mut object = Map::with_capacity(result.len() + 1);
    object.insert("ok".to_owned(), Value::Bool(true));
    object.extend(result);
    Value::Object(object)
}

/// A failure response. The `error` object may carry extra members per the
/// spec, but we send only `code` and `message`.
pub fn failure(error: &Error) -> Value {
    let mut detail = Map::new();
    detail.insert("code".to_owned(), Value::from(error.code.as_str()));
    detail.insert("message".to_owned(), Value::from(error.message.as_str()));

    let mut object = Map::new();
    object.insert("ok".to_owned(), Value::Bool(false));
    object.insert("error".to_owned(), Value::Object(detail));
    Value::Object(object)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::error::ErrorCode;
    use serde_json::json;

    #[test]
    fn success_with_no_members_is_just_ok() {
        assert_eq!(success(Map::new()), json!({"ok": true}));
    }

    #[test]
    fn success_carries_result_members() {
        let mut result = Map::new();
        result.insert("Now".to_owned(), json!(42));
        assert_eq!(success(result), json!({"ok": true, "Now": 42}));
    }

    #[test]
    fn failure_has_code_and_message_under_error() {
        let error = Error::new(ErrorCode::QueueDoesNotExist, "no queue named x");
        assert_eq!(
            failure(&error),
            json!({
                "ok": false,
                "error": {"code": "QueueDoesNotExist", "message": "no queue named x"}
            })
        );
    }
}
EOF
