        assert!(parse(json!({"Fifo": "true"})).is_err());
    }

    #[test]
    fn dead_letter_members_are_paired() {
        let both = parse(json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 5})).unwrap();
        assert_eq!(
