    let bodies: Vec<&str> = first.iter().map(|m| m["Body"].as_str().unwrap()).collect();
    assert_eq!(bodies, ["a1", "b1"], "a2 waits behind a1 in group A");
    assert_eq!(first[0]["SequenceNumber"], json!(1));
    assert_eq!(first[0]["GroupId"], json!("A"));
